#include <iostream>
using namespace std;

int sumTo(int n) {
    int total = 0;
    for (int i = 1; i <= n; i++) {
        total = total + i;
    }
    return total;
}

int main() {
    int n = 0;
    cin >> n;

    cout << "1 到 " << n << " 一共 " << sumTo(n) << " 条{unit}喵" << endl;
    return 0;
}
